import React, { useState, useEffect } from "react";
import { motion, AnimatePresence } from "framer-motion";
import { Menu, X, Phone, Sparkles } from "lucide-react";

const navLinks = [
  { label: "Home", href: "#top" },
  { label: "About", href: "#about" },
  { label: "Collections", href: "#collections" },
  { label: "Reviews", href: "#reviews" },
  { label: "Contact", href: "#contact" },
];

export default function Navbar({ onOpenQuote }) {
  const [scrolled, setScrolled] = useState(false);
  const [open, setOpen] = useState(false);

  useEffect(() => {
    const handleScroll = () => setScrolled(window.scrollY > 50);
    window.addEventListener("scroll", handleScroll, { passive: true });
    handleScroll();
    return () => window.removeEventListener("scroll", handleScroll);
  }, []);

  return (
    <>
      <header className={`navbar ${scrolled ? "scrolled" : ""}`}>
        <div className="container flex items-center justify-between">
          <a href="#top" className="flex items-center gap-2">
            <span className="serif text-lg sm:text-xl" style={{ color: "#d4af37", letterSpacing: "0.1em" }}>D SAJAWAT</span>
          </a>

          <nav className="hidden lg:flex items-center gap-8">
            {navLinks.map((link) => (
              <a key={link.href} href={link.href} className="text-sm font-medium hover:text-[#d4af37] transition-colors" style={{ color: scrolled ? "#1a080a" : "white" }}>{link.label}</a>
            ))}
          </nav>

          <div className="hidden lg:flex items-center gap-4">
            <a href="tel:+919888919983" className="flex items-center gap-2 text-sm" style={{ color: "#d4af37" }}><Phone size={16} /><span>Call Now</span></a>
            <button onClick={onOpenQuote} className="btn-primary"><Sparkles size={16} /><span>Get Quote</span></button>
          </div>

          <button className="lg:hidden p-2" onClick={() => setOpen(!open)} aria-label="Toggle menu">
            {open ? <X size={24} /> : <Menu size={24} />}
          </button>
        </div>
      </header>

      <AnimatePresence>
        {open && (
          <>
            <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} className="fixed inset-0 bg-black/50 z-40 lg:hidden" onClick={() => setOpen(false)} />
            <motion.div initial={{ x: "100%" }} animate={{ x: 0 }} exit={{ x: "100%" }} transition={{ type: "spring", damping: 25, stiffness: 200 }} className="fixed top-0 right-0 bottom-0 w-[280px] max-w-[80vw] z-50 lg:hidden" style={{ background: "#fdf8ed" }}>
              <div className="flex flex-col h-full p-6">
                <div className="flex justify-end mb-8"><button onClick={() => setOpen(false)} className="p-2"><X size={24} /></button></div>
                <nav className="flex flex-col gap-4 flex-1">
                  {navLinks.map((link, i) => (
                    <motion.a key={link.href} href={link.href} className="serif text-2xl" style={{ color: "#1a080a" }} initial={{ opacity: 0, x: 20 }} animate={{ opacity: 1, x: 0 }} transition={{ delay: i * 0.1 }} onClick={() => setOpen(false)}>{link.label}</motion.a>
                  ))}
                </nav>
                <div className="flex flex-col gap-3 pt-6 border-t" style={{ borderColor: "rgba(212,175,55,0.3)" }}>
                  <a href="tel:+919888919983" className="btn-secondary"><Phone size={18} /><span>Call Now</span></a>
                  <button onClick={() => { setOpen(false); onOpenQuote(); }} className="btn-primary"><Sparkles size={18} /><span>Get Quote</span></button>
                </div>
              </div>
            </motion.div>
          </>
        )}
      </AnimatePresence>
    </>
  );
}
